        return self.parse_primary_full(tokens, index)

    def parse_primary_full(self, tokens, index):
        if index >= len(tokens):
            raise SyntaxError("Unexpected end of expression")
        token = tokens[index]
        if token[0] == 'NUMBER':
            return token, index + 1
        elif token[0] == 'ID':
            id_name = token[1]
            if index + 1 < len(tokens) and tokens[index+1][0] == 'LPAREN':
                index += 2 # Skip ID and LPAREN
                args = []
                if tokens[index][0] != 'RPAREN':
                    while True:
                        arg_node, index = self.parse_expr_full(tokens, index)
                        args.append(arg_node)
                        if index < len(tokens) - 1 and tokens[index][0] == 'COMMA':
                            index += 1
                            continue
                        elif index < len(tokens) and tokens[index][0] == 'RPAREN':
                            index += 1
                            break
                        else:
                            raise SyntaxError("Expected ',' or ')'")
                else:
                    # index is already at RPAREN due to the skip
                    pass
                return ('CALL', id_name, args), index
            else:
                return ('VAR', id_name), index + 1
        elif token[0] == 'LPAREN':
            index += 1
            node, index = self.parse_expr_full(tokens, index)
            if index >= len(tokens) or tokens[index][0] != 'RPAREN':
                raise SyntaxError("Expected ')'")
            return node, index + 1
        else:
            raise SyntaxError(f"Unexpected token: {token[1]}")

    def parse_assignment_top(self, tokens, index):
        if index + 2 < len(tokens) and tokens[index][0] == 'ID' and tokens[index+1][0] == 'ASSIGN':
            var_name = tokens[index][1]
            node, next_index = self.parse_expr_full(tokens, index + 2)
            if next_index != len(tokens) - 1:
                raise SyntaxError("Syntax Error in assignment")
            return ('ASSIGN', var_name, node), next_index
        else:
            node, next_index = self.parse_expr_full(tokens, index)
            if next_index != len(tokens) - 1:
                raise SyntaxError("Syntax Error in expression")
            return node, next_index

    def evaluate(self, node):
        node_type = node[0]
        if node_type == 'NUMBER':
            return node[1]
        elif node_type == 'VAR':
            name = node[1]
            if name not in self.variables:
                raise NameError(f"NameError: name '{name}' is not defined")
            return self.variables[name]
        elif node_type == 'ASSIGN':
            val = self.evaluate(node[2])
            self.variables[node[1]] = val
            return val
        elif node_type == 'UNARY':
            val = self.evaluate(node[2])
            return -val if node[1] == '-' else val
        elif node_type == 'BINOP':
            op = node[1]
            left = self.evaluate(node[2])
            right = self.evaluate(node[3])
            if op == '+': return left + right
            if op == '-': return left - right
            if op == '*': return left * right
            if op == '/':
                if right == 0: raise ZeroDivisionError("division by zero")
                return left / right
            if op == '%':
                if right == 0: raise ZeroDivisionError("modulo by zero")
                return left % right
            if op == '**': return left ** right
        elif node_type == 'CALL':
            func_name = node[1]
            args = [self.evaluate(arg) for arg in node[2]]
            if func_name == 'abs': return abs(args[0])
            if func_name == 'min': return min(args)
            if func_name == 'max': return max(args)
            raise NameError(f"NameError: name '{func_name}' is not defined")
        return None

    def execute(self, code):
        self.variables = {}
        lines_to_process = []
        for line in code.split('\n'):
            line = line.split('#')[0].strip()
            if not line: continue
            for part in line.split(';'):
                p = part.strip()
                if p: lines_to_process.append(p)

        last_val = None
        for line in lines_to_process:
            tokens = self.tokenize(line)
            if not tokens or tokens[0][0] == 'EOF': continue
            node, next_index = self.parse_assignment_top(tokens, 0)
            if next_index != len(tokens) - 1:
                raise SyntaxError("Syntax Error")
            last_val = self.evaluate(node)
        return last_val

def calistir(program: str):
    return Interpreter().execute(program)
